mapper.update:
UPDATE post
content = #{content}, images = #{images, typeHandler=com.example.item.demo35.util.JsonListTypeHandler}, like_count = #{likeCount}, comment_count = #{commentCount},
WHERE id = #{id}

mapper.select:
SELECT p.*, u.name AS user_name, u.number AS user_number, u.email AS user_email, u.age AS user_age, u.sex AS user_sex, u.avatar AS user_avatar FROM post p LEFT JOIN user u ON p.user_id = u.id
WHERE p.user_id = #{userId}
ORDER BY p.create_time DESC
